$js = Get-Content "e:\HOMEPAGE\js\admin.js" -Raw -Encoding UTF8; $newLogic = "        // 3. Update Feature Distribution`n        const f = stats.features || { analyzer: 0, market: 0, news: 0, community: 0 };`n        const totalF = f.analyzer + f.market + f.news + f.community;`n        const getPct = (val) => totalF > 0 ? Math.round((val / totalF) * 100) : 0;`n        const setFeat = (id, pct) => {`n            const elPct = document.getElementById(id + '-pct');`n            const elBar = document.getElementById(id + '-bar');`n            if (elPct) elPct.innerText = pct + '%';`n            if (elBar) elBar.style.width = pct + '%';`n        };`n        if (totalF > 0) {`n            setFeat('admin-feat-analyzer', getPct(f.analyzer));`n            setFeat('admin-feat-market', getPct(f.market));`n            setFeat('admin-feat-news', getPct(f.news));`n            setFeat('admin-feat-community', getPct(f.community));`n        } else {`n            setFeat('admin-feat-analyzer', 0);`n            setFeat('admin-feat-market', 0);`n            setFeat('admin-feat-news', 0);`n            setFeat('admin-feat-community', 0);`n        }`n`n        // 4. Update Device Share`n        const setDev = (id, pct) => {`n            const el = document.getElementById(id);`n            if (el) el.innerText = pct + '%';`n        };`n        setDev('admin-dev-mobile-pct', stats.mobilePct);`n        setDev('admin-dev-desktop-pct', stats.desktopPct);`n    },`n`n    renderUsers: function () {"; $js = $js -replace "    \},`r?`n`r?`n    renderUsers: function \(\) \{", $newLogic; Set-Content "e:\HOMEPAGE\js\admin.js" $js -Encoding UTF8
